package com.collabspace.controller; import com.collabspace.dto.WorkspaceDtos.*; import com.collabspace.service.WorkspaceService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/workspaces") @RequiredArgsConstructor public class WorkspaceController {private final WorkspaceService s; @GetMapping public List<WorkspaceResponse> list(){return s.list();}@PostMapping public WorkspaceResponse create(@Valid @RequestBody CreateWorkspaceRequest r){return s.create(r);}@GetMapping("/{id}") public WorkspaceResponse get(@PathVariable UUID id){return s.get(id);}@PutMapping("/{id}") public WorkspaceResponse update(@PathVariable UUID id,@Valid @RequestBody UpdateWorkspaceRequest r){return s.update(id,r);}@DeleteMapping("/{id}") public void delete(@PathVariable UUID id){s.delete(id);}@PostMapping("/{id}/members") public void add(@PathVariable UUID id,@Valid @RequestBody AddMemberRequest r){s.addMember(id,r);}@DeleteMapping("/{id}/members/{userId}") public void remove(@PathVariable UUID id,@PathVariable UUID userId){s.removeMember(id,userId);}}